+import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';
+const W='acceptance/20261021-long-flow-090-w/',P=W+'scenario/东岸末班船-规模验证/',sha=b=>crypto.createHash('sha256').update(b).digest('hex'),state=JSON.parse(fs.readFileSync(P+'.writer/state.json'));
