+const rows=[
+[19,['许何试着有限换班，让何真正去私人会面','今天下午，你能不能早点来？'],['许要少睡并延后送旧灯','本来想中午躺一阵，起来再带旧灯去杂货店。'],['许只答两点半到五点并要求何准时接','那我少睡点。你五点来，别让我自己猜你还喝不喝第二壶。'],['何16:56实返，许提前走但倦仍留','四点五十六，老何到了。'],['双方能明确交还责任，家中女也接一段做饭','别替我拿着包了。']],
+[20,['沈要保住一顿可坐着吃的午饭','我现在吃。'],['店有赶一笼多卖的需求，老板也累','就这一笼，做出来也能放到下午。'],['不加那一笼、现货售完，轮流吃饭','说下午少一笼便少一笼，现有的卖完就收'],['十份只售六，四份损失不由裁布抵消','没卖出的那四份却不是一句“也许”便能抹掉'],['父对袋仍有自己的意愿，沈不越过所有人先拆','我看一眼。拆还得拿针。']],
+[21,['把未完凳做成并把小技能用于真实袋边','做好了。我晚一点送过去，你那边现在放得开么？'],['窄面/雨水/厚褶都施加具体限制','这里不行。'],['姑娘只修能落针处，厚处退针','她停下，将针退回来'],['凳工料84实际收，袋返父轻用有变化','收到钱夹里'],['借自有画册产生新往来，非修袋报酬','我从这儿看的。你不用从这儿看。']],
+[22,['按21约定真实还书','今天三点还。'],['沈仍营业，借物与饭盒需要腾手分放','看见沈禾两只手都在忙'],['姑娘不催柜台，沈在约时亲接','沈禾擦干手，从她手里接过书'],['书由沈带家归床头，借还结束','书便稳稳躺住'],['各自看图可以有不同趣味，不只交换帮助','那这幅可热闹了，一件衣服还去拿另一件。']],
+[23,['收摊和收工各有个人用途','今晚想早点回去，把家里那堆没洗的衣服先泡上。'],['凳仍占地，想改尺寸会占周当晚','要不再收窄两公分？二十八也还占地方。'],['周拒今晚改，廖自行试可收位置','我知道。说今晚做，我也做不了。'],['周真回家吃洗，廖试收位再搬营业','再把湿衣挂上去'],['沈父指出吃完清洗也是本人要做的事','我说的是洗。吃完我总得洗。']],
+[24,['把有限学习落实到母亲真实可穿的一处','好了这一处。你穿穿。'],['新手误带两针、折角与尺寸都有阻力','自己有两针带住了袖筒另一面的布'],['本人拆错重来，不全剪重做','先把勾住的两针挑出来'],['母实际试穿收柜；凳袋也有当日实际去处','脱下工装，自己叠进柜里'],['母接受女有限成果，父也能自行拒延伸路程','我答应了。又没叫你拆。']]
+];
+const keys=['goal','obstacle','choice','consequence','relationship_change'],functions=rows.map(([unit,...v])=>({unit,...Object.fromEntries(v.map(([text,quote],i)=>[keys[i],{status:'observed',text,evidence:[{unit,quote}]}]))}));
+const pairs=[
+{units:[19,20],judgment:'均以时间分配和吃饭承接劳动，具有相似的有限让步结构。',differences:'19是同事换班、私人的睡眠和送灯机会损失；20是雇佣劳动中午饭与真实少售四份，代价归属和不快不同。',preserve:'保留何准时回来和老板未变成全然赞同的对照。',optional_adjustments:[],uncertainty:'节奏判断为本会话知情阅读，未有陌生读者体验。',evidence:[{unit:19,quote:'那我少睡点。你五点来，别让我自己猜你还喝不喝第二壶。'},{unit:20,quote:'没卖出的那四份却不是一句“也许”便能抹掉'}]},
+{units:[21,24],judgment:'两章均写取针、遇阻、调整、收针，属于学习与应用的相似工序。',differences:'21主动避开厚褶，只合小段；24第二课能在指导下处理一处母袖，误带另一面后自己拆回，母实际试穿构成新关系结果。',preserve:'保留21退针和24不齐/角硬/色深，不把成长变成全面专业能力。',optional_adjustments:['今后若整书压缩，可优先看重复收线动作是否仍需逐次展开，不在本次擅改已登记稿。'],uncertainty:'未验证真实缝纫工时和耐久；这里只核小说中有限行动能成立。',evidence:[{unit:21,quote:'她停下，将针退回来'},{unit:24,quote:'自己有两针带住了袖筒另一面的布'}]},
+{units:[22,23],judgment:'两章都有取放、试比和归位，但不是同一次验物重演。',differences:'22归还借书并在看图中建立独立兴趣、试洗候选料；23试收位失败再找干位，布已干后真裁，沈父从等饭转向自己处理洗锅拿碗。',preserve:'保留22白纸随书与23有柄深碗的不同使用后果，物件不能只列名。',optional_adjustments:[],uncertainty:'整理场景密度偏高是风格观察，未形成独立硬伤。',evidence:[{unit:22,quote:'书便稳稳躺住'},{unit:23,quote:'我说的是洗。吃完我总得洗。'}]},
+{units:[23,24],judgment:'侧放长凳和端盆通过重复出现，先试后用形成承接。',differences:'23是本人腾地试位并与周讨论拒当晚改；24是营业中本人坐吃以及夜末真的收妥、清葱皮，有限习惯发生而非只约定。',preserve:'保留四脚落地和旧靠背椅、宽面仍占地的代价，不写永久省事。',optional_adjustments:['后续全书审修可比较两次侧送动作的叙述长度；当前保留试验到实行的必要因果。'],uncertainty:'只写一天重复实践，不能推长期省时或安全保证。',evidence:[{unit:23,quote:'凳子终于可以自己待着'},{unit:24,quote:'四脚仍落地，长边贴里墙送入'}]},
+{units:[19,22,24],judgment:'饭后收物与母女晚间同处反复成为缓和段落，存在结构趋同倾向。',differences:'19把少睡后倦与女分担做饭留下，22各自阅读借还和选材料，24母实际穿补衣并各自外吃后相聚；核心变化各异。',preserve:'保留慢热声音、当面玩笑和自主吃饭，未要求每章另造危机。',optional_adjustments:['未来若压缩节奏，可优先审视饭尾和灯/盒收放的篇幅，而非删除人物的日常趣味。'],uncertainty:'这是可选风格风险，非确认重复到无新信息；没有真人盲读或市场数据。',evidence:[{unit:19,quote:'她靠着坐稳，这回没有设闹钟。'},{unit:22,quote:'歪着的那只篮子留在外面，没有撕掉。'},{unit:24,quote:'我答应了。又没叫你拆。'}]}
+];
