text(await tools.exec_command({cmd:"node acceptance/20261021-long-flow-090-w/w-writer.mjs d-stop-identify tool identify",max_output_tokens:600}));
text(await tools.apply_patch("*** Begin Patch
*** Add File: D:/work/other/ai-writer/acceptance/20261021-long-flow-090-w/d-final-audit.mjs
+import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
+const W=path.dirname(fileURLToPath(import.meta.url)),ROOT=path.resolve(W,'../..'),read=f=>JSON.parse(fs.readFileSync(f)),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
+const s=read(path.join(W,'d-active-revision.json')),P=s.main_project,C=s.workspace,pre=read(path.join(W,'pre-revision-current.json')),base=read(path.join(W,'d-revision-main-baseline.json')),start=read(path.join(W,'d-start-baseline.json')),mainRaw=fs.readFileSync(path.join(P,'.writer/state.json')),candRaw=fs.readFileSync(path.join(C,'.writer/state.json')),m=JSON.parse(mainRaw),c=JSON.parse(candRaw),diff=read(path.join(W,'d-revision-changed-current.json'));
+assert.equal(m.revision,97);assert.equal(c.revision,99);assert.equal(sha(mainRaw),base.state_sha256);assert.deepEqual(m.units,pre.state.units);assert.equal(m.units.length,24);assert.deepEqual(c.units.map(u=>u.unit),Array.from({length:13},(_,i)=>i+1));assert.deepEqual(c.units.slice(0,12),pre.state.units.slice(0,12));assert.deepEqual(m.units.slice(0,12),start.state.units.slice(0,12));
+const observations=st=>Object.fromEntries(Object.entries(st.snapshot.ledger).filter(([,v])=>v.type==='observation').map(([k,v])=>[k,{type:v.type,statement:v.statement,...(Object.hasOwn(v,'author_truth')?{author_truth:v.author_truth}:{})}]));
+assert.deepEqual(observations(m),pre.observations);assert.deepEqual(observations(c),pre.observations);assert.deepEqual(observations(m),start.observations);
+const allDrafts=[];
+for(const d of pre.drafts){const a=fs.readFileSync(path.join(P,d.draft)),b=fs.readFileSync(path.join(C,d.draft)),old=fs.readFileSync(path.join(W,'originals/d-revision-main24',d.draft));assert.equal(sha(a),d.sha256);assert.equal(sha(old),d.sha256);const change=diff.changed.find(x=>x.unit===d.unit);assert.equal(sha(b),change?change.new_sha256:d.sha256);allDrafts.push({...d,candidate_sha256:sha(b),candidate_body_han:(b.toString('utf8').replace(/^#.*\r?\n/,'').match(/\p{Script=Han}/gu)||[]).length,candidate_registered:d.unit<=13});}
+const sourceRefs=[...new Set(pre.state.units.flatMap(u=>Object.keys(u.source_hashes)).filter(x=>x!=='.writer/state.json'&&!x.startsWith('正文/')))];
+for(const ref of sourceRefs)assert.equal(sha(fs.readFileSync(path.join(P,ref))),sha(fs.readFileSync(path.join(C,ref))),`source entry edited ${ref}`);
+const frozen=read(path.join(W,'product-frozen-current.json')),delivery=read(path.join(W,'delivery-current.json'));
+for(const f of frozen.files)assert.equal(sha(fs.readFileSync(path.join(ROOT,f.file))),f.sha256,`root frozen file changed ${f.file}`);
+assert.equal(sha(fs.readFileSync(delivery.archive)),delivery.archive_sha256);assert.equal(delivery.content_id,frozen.content_id);
+const cli=label=>read(path.join(W,'cli-logs',label,'stdout.raw.txt')),identify=cli('d-stop-identify'),list=cli('d-stop-revision-list'),cs=cli('d-stop-candidate-status'),ms=cli('d-stop-main-status');
+assert.equal(identify.ok,true);assert.equal(identify.observed_content_id,delivery.content_id);assert.equal(ms.tool_control.generation,2);assert.equal(cs.next_unit,14);assert.equal(ms.next_unit,25);assert.deepEqual(ms.stale_units,[]);assert.deepEqual(cs.stale_units,[]);assert.deepEqual(ms.changed_sources,[]);assert.deepEqual(cs.changed_sources,[]);assert.deepEqual(cs.impact_pending,[]);
+const active=list.sessions.filter(x=>!['committed','aborted'].includes(x.status));assert.equal(active.length,1);assert.equal(active[0].id,s.id);assert.equal(active[0].owner,s.owner);assert.equal(active[0].status,'editing');assert.equal(list.transactions.filter(x=>x.status!=='completed').length,0);
+const logs=[];for(const label of fs.readdirSync(path.join(W,'cli-logs')).filter(x=>x.startsWith('d-'))){const r=read(path.join(W,'cli-logs',label,'result.json'));logs.push({label,exit_code:r.exit_code,before_state_sha256:r.before_state_sha256,after_state_sha256:r.after_state_sha256,stdout_bytes:r.stdout_bytes,stderr_bytes:r.stderr_bytes});}logs.sort((a,b)=>a.label.localeCompare(b.label));
+const failures=logs.filter(x=>x.exit_code!==0);assert.deepEqual(failures.map(x=>x.label),['d-authorize-draft']);
+const audit={at:new Date().toISOString(),main_project:P,candidate_workspace:C,session_id:s.id,owner:s.owner,base_revision:s.base_revision,main_revision:m.revision,candidate_revision:c.revision,main_state_sha256:sha(mainRaw),candidate_state_sha256:sha(candRaw),main_units_24_exact_pre_revision:true,main_body_24_exact_pre_revision:true,prefix_12_units_exact_start_and_pre_revision:true,candidate_prefix_12_units_exact:true,prefix_12_body_exact:true,all_original_bytes_preserved:true,observations:observations(c),observation_three_fields_exact:true,source_entries_compared:sourceRefs.length,source_entries_unchanged:true,root_frozen_files_compared:frozen.files.length,root_frozen_files_unchanged:true,archive_sha256:delivery.archive_sha256,archive_unchanged:true,content_id:identify.observed_content_id,runtime_id:identify.runtime_id,generation:ms.tool_control.generation,session:active[0],pending_transactions:[],main_next_unit:ms.next_unit,candidate_next_unit:cs.next_unit,candidate_registered_units:c.units.map(x=>x.unit),changed_candidate_units:diff.changed.map(x=>x.unit),not_replayed:Array.from({length:11},(_,i)=>i+14),allDrafts,cli_logs:logs.length,cli_failures:failures,notes:['未prepare/commit/abort；未重登14；无手改state或消费哈希。','候选14—24改过部分正文仍未重登，不是已完成修订验收；根需核占用后同ID恢复。','所有SHA比较均为机械字节保护证据，文学阅读结论见实际报告。']};
+fs.writeFileSync(path.join(W,'d-protection-final.json'),JSON.stringify(audit,null,2)+'\n',{flag:'wx'});
